227→                    <InlineStack gap="200" blockAlign="center">
228→                      <Badge tone={planBadgeTone}>{`${planLabel} Plan`}</Badge>
229→                      {subscription.planTier !== "free" && (
230→                        <Text as="span" tone="subdued" variant="bodySm">
231→                          {subscription.billingInterval === "annual"
