242→                  </BlockStack>
243→                  <Button
244→                    variant="primary"
245→                    onClick={() => navigate("/app/pricing")}
246→                  >
247→                    {subscription.planTier === "free" || subscription.planTier === "starter"
248→                      ? "Upgrade Plan"
249→                      : "Manage Plan"}
250→                  </Button>
251→                </InlineStack>
252→              </BlockStack>
253→            </Card>
254→          </Layout.Section>
255→
256→          {/* ----------------------------------------------------------------
257→              Section 2: Default Behavior for Unknown Zip Codes (NEW)
