122→// ─── Loader ───────────────────────────────────────────────────────────────────
123→
124→export const loader = async ({ request }: LoaderFunctionArgs) => {
125→  const { session } = await authenticate.admin(request);
126→  const shop = session.shop;
127→  const subscription = await getShopSubscription(shop);
