252→// ── Scope custom CSS for admin preview — prefix selectors with #wid ─────────
253→function scopeAdminCss(rawCss: string | null | undefined, wid: string): string {
254→  if (!rawCss) return "";
255→  const css = rawCss.replace(/<\/style>/gi, "");
256→  let result = "";
257→  let remaining = css;
258→  while (remaining.length > 0) {
259→    const openBrace = remaining.indexOf("{");
260→    if (openBrace === -1) break;
261→    const closeBrace = remaining.indexOf("}", openBrace);
262→    if (closeBrace === -1) break;
263→    const selector = remaining.substring(0, openBrace).trim();
264→    const body = remaining.substring(openBrace + 1, closeBrace);
265→    remaining = remaining.substring(closeBrace + 1);
266→    if (selector.startsWith("@")) {
267→      result += selector + "{" + body + "}";
268→    } else if (selector) {
269→      const prefixed = selector.split(",").map(s => {
270→        s = s.trim();
271→        return s ? "#" + wid + " " + s : "";
272→      }).filter(Boolean).join(", ");
273→      result += prefixed + " {" + body + "}";
274→    }
275→  }
276→  return result;
277→}
